/*
 * prog58_turing_increment
 *
 * The program receives a single command‑line argument that must be a
 * non‑empty string of at most 31 characters, each character being either
 * '0' or '1'.  The string is interpreted as a binary number with the
 * *least‑significant bit first* (the first character is the LSB).
 *
 * The program increments that binary number by one using a Turing‑machine‑like
 * algorithm.  It prints the resulting bit string (still LSB‑first) together
 * with the number of steps (cells examined) that the algorithm performed.
 *
 * If the input consists only of '1' bits, the increment would overflow the
 * fixed‑size tape; in that case the program prints “OVERFLOW” and the step
 * count.  For any malformed input it prints “INVALID_INPUT”.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_LEN 31          /* limit imposed by the original binary */

int main(int argc, char **argv)
{
    /* ----- argument validation ----- */
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *in = argv[1];
    size_t len = strlen(in);

    if (len == 0 || len > MAX_LEN) {
        puts("INVALID_INPUT");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        if (in[i] != '0' && in[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }

    /* ----- copy input to the tape ----- */
    char tape[MAX_LEN];
    memcpy(tape, in, len);          /* tape holds the bits, LSB at index 0 */

    /* ----- increment algorithm (LSB‑first) ----- */
    int steps = 0;                   /* number of cells examined */
    int pos   = 0;                   /* head position, starts at LSB */

    while (1) {
        if (tape[pos] == '0') {
            /* we can flip this 0 to 1 and stop */
            tape[pos] = '1';
            ++steps;
            break;
        } else {
            /* current bit is 1 → turn it into 0 and carry */
            tape[pos] = '0';
            ++steps;

            if (pos == (int)len - 1) {
                /* we have carried past the most‑significant bit → overflow */
                puts("OVERFLOW");
                printf(" steps=%d\n", steps);
                return 0;
            }
            ++pos;   /* move to the next more‑significant bit */
        }
    }

    /* ----- output the result ----- */
    printf("result=");
    for (size_t i = 0; i < len; ++i) {
        putchar(tape[i]);
    }
    printf(" steps=%d\n", steps);
    return 0;
}
